            if best is None or len(sel)>len(best): best=sel[:]
            return
        choose(i+1,used,sel)
        if not squares[i]&used: choose(i+1,used|squares[i],sel+[squares[i]])
    choose(0,set(),[])
    used=set()
    for q in best or []:
