def transform(grid):
    h,w=len(grid),len(grid[0])
    cells={(r,c) for r in range(h) for c in range(w) if grid[r][c] != 0}
    pieces=[]
    # Square tiles become color 1.
    for r in range(h-1):
        for c in range(w-1):
            q=frozenset((y,x) for y in (r,r+1) for x in (c,c+1))
            if q <= cells: pieces.append((q,1))
    # L triominoes, colored by the missing corner of their 2x2 bounding box.
    # mapping missing TL/TR/BL/BR -> 2/4/3/5
    cmap={0:2,1:4,2:3,3:5}
    for r in range(h-1):
        for c in range(w-1):
            box=[(r,c),(r,c+1),(r+1,c),(r+1,c+1)]
            for i in range(4):
                q=frozenset(box[j] for j in range(4) if j!=i)
                if q <= cells: pieces.append((q,cmap[i]))
    bycell={p:[] for p in cells}
    for q,col in pieces:
        for p in q: bycell[p].append((q,col))
    best=None
    def search(rem, selected):
        nonlocal best
        if not rem:
            # Prefer maximum square count; then known 2/3/4-only L types.
            score=(sum(col==1 for q,col in selected),-sum(col==5 for q,col in selected))
            if best is None or score>best[0]: best=(score,selected[:])
            return
        if best and sum(col==1 for q,col in selected)+len(rem)//4 < best[0][0]: return
        p=min(rem,key=lambda p:sum(q<=rem for q,col in bycell[p]))
        for q,col in bycell[p]:
            if q<=rem: search(rem-q,selected+[(q,col)])
    search(cells,[])
    out=[[0]*w for _ in range(h)]
    if best:
        for q,col in best[1]:
            for r,c in q: out[r][c]=col
    return out
